static int g_path;
static void InsertionSort(E* first, E* last)                      // stable, by SortValue
{
    for (E* i = first + 1; i < last; ++i) { E v = *i; E* j = i; while (j > first && v < *(j - 1)) { *j = *(j - 1); --j; } *j = v; }
}
